// Commitments + installments daily cron (Vercel cron — see vercel.json,
// 30 15 * * *). Three jobs, each gated on a status transition so re-runs and
// double fires never duplicate work:
//   1. Promised commitments whose invoice is now paid → kept.
//   2. Promised commitments whose date has passed unpaid → broken; the
//      conversation goes to broken_promise and a follow-up draft lands in the
//      review inbox.
//   3. Installments due today (pending) → mint a Stripe payment link and queue
//      the installment email for approval; installments past due & unpaid →
//      overdue, with a nudge draft queued.
//
// CRON_SECRET Bearer auth, ?userId= scoping, demo-skip — the shared patterns.
// Everything the cron queues is pending_review (approve-before-send holds).

import { NextResponse, type NextRequest } from "next/server";
import { revalidateUser } from "@compound/db-cache";
import { adminSupabase } from "@/app/_lib/supabase/admin";
import { DEMO_EMAIL } from "@/app/_lib/demo";
import { ensureConversation } from "@/app/_lib/conversations";
import { applyTransition } from "@/app/_lib/agent/state";
import { createInstallmentPaymentLink } from "@/app/_lib/integrations/stripe-connect";
import { formatCents } from "@/app/_lib/format";

export const runtime = "nodejs";
export const maxDuration = 300;
export const dynamic = "force-dynamic";

function authorized(req: NextRequest): boolean {
  const secret = process.env.CRON_SECRET;
  if (!secret) return false;
  return req.headers.get("authorization") === `Bearer ${secret}`;
}

function todayIso(now: Date): string {
  return now.toISOString().slice(0, 10);
}

async function handle(req: NextRequest) {
  if (!authorized(req)) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const onlyUserId = req.nextUrl.searchParams.get("userId") ?? undefined;
  const sb = adminSupabase();
  const now = new Date();
  const today = todayIso(now);

  const demoId = onlyUserId
    ? null
    : (await sb.auth.admin.listUsers({ page: 1, perPage: 200 })).data?.users.find(
        (u) => u.email === DEMO_EMAIL,
      )?.id ?? null;

  let kept = 0;
  let broken = 0;
  let linksMinted = 0;
  let overdue = 0;
  const touched = new Set<string>();

  /* ── 1 & 2: commitments ──────────────────────────────────────────────── */
  let cq = sb
    .from("invoices_commitments")
    .select("id, user_id, conversation_id, invoice_id, promised_date")
    .eq("status", "promised");
  if (onlyUserId) cq = cq.eq("user_id", onlyUserId);
  const { data: commitments } = await cq;

  for (const c of commitments ?? []) {
    const userId = c.user_id as string;
    if (demoId && userId === demoId) continue;

    const { data: inv } = await sb
      .from("invoices_invoices")
      .select("id, client_id, invoice_number, status")
      .eq("user_id", userId)
      .eq("id", c.invoice_id)
      .maybeSingle();
    if (!inv) continue;

    if (inv.status === "paid") {
      const { data: t } = await sb
        .from("invoices_commitments")
        .update({ status: "kept", updated_at: now.toISOString() })
        .eq("id", c.id)
        .eq("status", "promised")
        .select("id");
      if (t?.length) {
        kept++;
        touched.add(userId);
      }
      continue;
    }

    // Promised date passed with the invoice still unpaid → broken.
    if ((c.promised_date as string) < today) {
      const { data: t } = await sb
        .from("invoices_commitments")
        .update({ status: "broken", updated_at: now.toISOString() })
        .eq("id", c.id)
        .eq("status", "promised")
        .select("id");
      if (!t?.length) continue; // lost the race — another run handled it
      broken++;
      touched.add(userId);

      const convo = await ensureConversation({
        userId,
        invoiceId: inv.id as string,
        clientId: (inv.client_id as string | null) ?? null,
      });
      if (convo) {
        await applyTransition(convo.id, { type: "commitment_broken" });
        await sb.from("invoices_messages").insert({
          user_id: userId,
          conversation_id: convo.id,
          invoice_id: inv.id,
          client_id: (inv.client_id as string | null) ?? null,
          direction: "out",
          channel: "email",
          subject: `Following up · ${inv.invoice_number}`,
          body:
            `Hi, just following up — you'd mentioned settling ${inv.invoice_number} by ` +
            `${c.promised_date}, and it looks like it hasn't come through yet. ` +
            `Could you let me know the status? Happy to help if anything's in the way. Thank you!`,
          status: "pending_review",
        });
      }
    }
  }

  /* ── 3: installments ─────────────────────────────────────────────────── */
  let iq = sb
    .from("invoices_installments")
    .select("id, user_id, invoice_id, conversation_id, seq, amount_cents, due_date, status, stripe_payment_link_url")
    .in("status", ["pending", "link_sent"]);
  if (onlyUserId) iq = iq.eq("user_id", onlyUserId);
  const { data: installments } = await iq;

  for (const inst of installments ?? []) {
    const userId = inst.user_id as string;
    if (demoId && userId === demoId) continue;
    const dueDate = inst.due_date as string;

    // Due today (or earlier) and not yet linked → mint the link + queue email.
    if (inst.status === "pending" && dueDate <= today) {
      const { data: invRow } = await sb
        .from("invoices_invoices")
        .select("id, client_id, invoice_number")
        .eq("user_id", userId)
        .eq("id", inst.invoice_id)
        .maybeSingle();
      if (!invRow) continue;

      const url = await createInstallmentPaymentLink(
        userId,
        {
          id: inst.id as string,
          invoice_id: inst.invoice_id as string,
          seq: inst.seq as number,
          amount_cents: inst.amount_cents as number,
          stripe_payment_link_url: inst.stripe_payment_link_url as string | null,
        },
        invRow.invoice_number as string,
      );
      // THIS COUNTED EVERY ATTEMPT. `createInstallmentPaymentLink` answers
      // null whenever Stripe is unreachable (no secret key, no connected
      // account) and the counter went up anyway, so the cron's own response
      // reported links that do not exist while the rows carried none. The
      // response is what an operator and a log reader both believe.
      if (url) linksMinted++;
      touched.add(userId);

      const convo =
        (inst.conversation_id as string | null) ??
        (await ensureConversation({
          userId,
          invoiceId: inst.invoice_id as string,
          clientId: (invRow.client_id as string | null) ?? null,
        }))?.id ??
        null;
      if (convo) {
        const payLine = url ? `\n\nYou can pay it here: ${url}` : "";
        await sb.from("invoices_messages").insert({
          user_id: userId,
          conversation_id: convo,
          invoice_id: inst.invoice_id,
          client_id: (invRow.client_id as string | null) ?? null,
          direction: "out",
          channel: "email",
          subject: `Payment ${inst.seq} · ${invRow.invoice_number}`,
          body:
            `Hi — this is a friendly reminder that payment ${inst.seq} of your plan for ` +
            `${invRow.invoice_number}, ${formatCents(inst.amount_cents as number)}, is due today.${payLine}\n\nThank you!`,
          status: "pending_review",
        });
      }
      continue;
    }

    // Strictly past due and still unpaid → overdue + a nudge draft.
    if (dueDate < today) {
      const { data: t } = await sb
        .from("invoices_installments")
        .update({ status: "overdue", updated_at: now.toISOString() })
        .eq("id", inst.id)
        .in("status", ["pending", "link_sent"])
        .select("id, invoice_id");
      if (!t?.length) continue;
      overdue++;
      touched.add(userId);

      const { data: invRow } = await sb
        .from("invoices_invoices")
        .select("id, client_id, invoice_number")
        .eq("user_id", userId)
        .eq("id", inst.invoice_id)
        .maybeSingle();
      const convo =
        (inst.conversation_id as string | null) ??
        (invRow
          ? (
              await ensureConversation({
                userId,
                invoiceId: inst.invoice_id as string,
                clientId: (invRow.client_id as string | null) ?? null,
              })
            )?.id ?? null
          : null);
      if (convo && invRow) {
        const payLine = inst.stripe_payment_link_url ? `\n\nHere's the link: ${inst.stripe_payment_link_url}` : "";
        await sb.from("invoices_messages").insert({
          user_id: userId,
          conversation_id: convo,
          invoice_id: inst.invoice_id,
          client_id: (invRow.client_id as string | null) ?? null,
          direction: "out",
          channel: "email",
          subject: `Missed payment ${inst.seq} · ${invRow.invoice_number}`,
          body:
            `Hi — payment ${inst.seq} of your plan for ${invRow.invoice_number}, ` +
            `${formatCents(inst.amount_cents as number)}, was due ${dueDate} and hasn't come through yet.${payLine}\n\n` +
            `Could you let me know when it'll go out? Thank you!`,
          status: "pending_review",
        });
      }
    }
  }

  for (const uid of touched) revalidateUser("invoices", ["invoices", "conversations"], uid);

  return NextResponse.json({ kept, broken, linksMinted, overdue, users: touched.size });
}

export const GET = handle;
export const POST = handle;
